import React from 'react';

const PageContainer = ({ children, style = {}, middleContent }) => {
  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <div style={{ 
        width: '1200px', 
        margin: '0 auto', 
        background: 'rgba(255, 255, 255, 0.5)', 
        borderRadius: '12px', 
        padding: '2rem', 
        boxShadow: 'rgba(0, 0, 0, 0.1) 0px 4px 12px',
        flex: '1 0 auto',
        ...style
      }} className="main-container">
        {children}
      </div>
      
      {/* Middle Content Container - between main content and footer */}
      {middleContent && (
        <div style={{
          width: '100%',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          padding: '1rem 0',
          flexShrink: 0
        }}>
          {middleContent}
        </div>
      )}
      
      {/* Copyright Footer - below main container, not fixed */}
      <div style={{
        width: '100%',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        padding: '2rem 0 1rem 0',
        flexShrink: 0
      }}>
        <footer style={{
          background: 'rgba(255,255,255,0.85)',
          borderRadius: '12px',
          boxShadow: '0 2px 10px rgba(0,0,0,0.08)',
          padding: '1rem 2rem',
          border: '1px solid rgba(40,167,69,0.15)',
          color: 'rgb(0,0,0)',
          fontSize: '0.9rem',
          fontWeight: 600,
          textShadow: '0 1px 3px rgba(255,255,255,0.8)',
          textAlign: 'center'
        }}>
          © 2025 The Moothedath Ancestral House. All rights reserved. | Preserving family heritage and memories for generations to come.
        </footer>
      </div>
    </div>
  );
};

export default PageContainer; 