import React, { useRef, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const videoStyles = {
  position: 'fixed',
  top: 0,
  left: 0,
  minWidth: '100vw',
  minHeight: '100vh',
  width: 'auto',
  height: 'auto',
  zIndex: 9999,
  objectFit: 'cover',
};

const textStyles = {
  position: 'fixed',
  left: '50%',
  top: '50%',
  transform: 'translate(-50%, calc(-50% - 40px))',
  color: 'pink',
  WebkitTextStroke: '2px black',
  textStroke: '2px black',
  fontSize: '100px',
  fontFamily: 'Segoe UI, Arial, sans-serif',
  letterSpacing: '2px',
  zIndex: 10000,
  display: 'none',
  textTransform: 'uppercase',
  textDecoration: 'underline',
  textDecorationColor: 'red',
  textUnderlineOffset: '0.15em',
  whiteSpace: 'nowrap',
  cursor: 'pointer',
  textShadow: `0 2px 8px rgba(0,0,0,0.7),
    2px 0 0 #fff,
    -2px 0 0 #fff,
    0 2px 0 #fff,
    0 -2px 0 #fff,
    4px 4px 0 #b30000,
    8px 8px 16px #000,
    1px 1px 0 #800000,
    2px 2px 2px #333`
};

const overlayStyles = {
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100vw',
  height: '100vh',
  background: 'rgba(0,0,0,0.45)',
  color: '#fff',
  zIndex: 20000,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  fontSize: '2rem',
  fontFamily: 'Segoe UI, Arial, sans-serif',
  cursor: 'pointer',
  textAlign: 'center',
};

const zoomOutCenter = `@keyframes zoomOutCenter {
  0% {
    opacity: 0;
    transform: translate(-50%, calc(-50% - 40px)) scale(0.1);
  }
  60% {
    opacity: 1;
    transform: translate(-50%, calc(-50% - 40px)) scale(1.2);
  }
  100% {
    opacity: 1;
    transform: translate(-50%, calc(-50% - 40px)) scale(1);
  }
}`;

const floatText = `@keyframes floatText {
  0% {
    transform: translate(-50%, calc(-50% - 40px)) scale(1);
  }
  50% {
    transform: translate(-50%, calc(-52% - 40px)) scale(1.04);
  }
  100% {
    transform: translate(-50%, calc(-50% - 40px)) scale(1);
  }
}`;

const colorChange = `@keyframes colorChange {
  0% { color: #ff0000; }
  14% { color: #ff8000; }
  28% { color: #ffff00; }
  42% { color: #00ff00; }
  56% { color: #0080ff; }
  70% { color: #8000ff; }
  84% { color: #ff0080; }
  100% { color: #ff0000; }
}`;

function Intro() {
  const textRef = useRef(null);
  const videoRef = useRef(null);
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [hasError, setHasError] = useState(false);
  const [currentVideo, setCurrentVideo] = useState(0);

  // Array of video sources in order of preference
  const videoSources = [
    { src: `${process.env.PUBLIC_URL}/main-wall.mp4`, type: 'video/mp4' },
    { src: `${process.env.PUBLIC_URL}/Wallpaper-1.mp4`, type: 'video/mp4' },
    { src: `${process.env.PUBLIC_URL}/placeholder-video.mp4`, type: 'video/mp4' } // Fallback video
  ];

  useEffect(() => {
    // Reset loading state when video source changes
    setIsLoading(true);
    setHasError(false);
    
    const video = videoRef.current;
    if (!video) return;
    
    // Set up video source
    video.src = videoSources[currentVideo].src;
    video.load();
    
    const playVideo = async () => {
      try {
        await video.play();
        setIsLoading(false);
      } catch (error) {
        console.log('Autoplay prevented or failed:', error);
        // If autoplay is prevented, we'll rely on user interaction
        setIsLoading(false);
      }
    };
    
    playVideo();
    
    // Cleanup function
    return () => {
      if (video) {
        video.pause();
        video.removeAttribute('src');
        video.load();
      }
    };
  }, [currentVideo]);

  const handleVideoEnd = () => {
    document.body.style.background = 'black';
    if (videoRef.current) videoRef.current.style.display = 'none';
    if (textRef.current) {
      textRef.current.style.display = 'block';
      textRef.current.classList.add('zoom-out-center');
      const handler = () => {
        textRef.current.classList.remove('zoom-out-center');
        textRef.current.classList.add('float-center');
        textRef.current.removeEventListener('animationend', handler);
      };
      textRef.current.addEventListener('animationend', handler);
    }
  };

  const handleTextClick = () => {
    navigate('/home');
  };

  // Allow user to enable audio by clicking anywhere on the video area
  const handleEnableAudio = () => {
    if (videoRef.current) {
      videoRef.current.muted = false;
      videoRef.current.play().catch(error => {
        console.log('Audio enable failed:', error);
      });
    }
  };

  const handleVideoError = () => {
    console.log(`Error loading video: ${videoSources[currentVideo].src}`);
    
    // Try the next video in the sources array
    if (currentVideo < videoSources.length - 1) {
      console.log('Trying next video source...');
      setCurrentVideo(prev => prev + 1);
    } else {
      // No more fallbacks, show error state
      console.log('All video sources failed to load');
      setHasError(true);
      setIsLoading(false);
      document.body.style.background = 'linear-gradient(135deg, #1a1a1a 0%, #2c3e50 100%)';
      handleVideoEnd();
    }
  };

  const handleVideoLoadStart = () => {
    console.log(`Loading video: ${videoSources[currentVideo].src}`);
    setIsLoading(true);
  };

  const handleVideoCanPlay = () => {
    console.log(`Video ready to play: ${videoSources[currentVideo].src}`);
    setIsLoading(false);
  };
  
  const handleVideoCanPlayThrough = () => {
    console.log(`Video can play through: ${videoSources[currentVideo].src}`);
    setIsLoading(false);
  };

  return (
    <>
      <style>{zoomOutCenter + floatText + colorChange}
      {`.zoom-out-center { 
        animation: zoomOutCenter 1.2s cubic-bezier(0.23, 1.01, 0.32, 1) forwards, colorChange 8s ease-in-out infinite !important; 
      }`}
      {`.float-center { 
        animation: floatText 2.5s ease-in-out infinite, colorChange 8s ease-in-out infinite !important; 
      }`}
      {`#bottom-center-text.zoom-out-center,
        #bottom-center-text.float-center,
        .moothedath-text.zoom-out-center,
        .moothedath-text.float-center {
        animation: zoomOutCenter 1.2s cubic-bezier(0.23, 1.01, 0.32, 1) forwards, colorChange 8s ease-in-out infinite !important;
      }`}
      {`#bottom-center-text.float-center,
        .moothedath-text.float-center {
        animation: floatText 2.5s ease-in-out infinite, colorChange 8s ease-in-out infinite !important;
      }`}
      {`@keyframes spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
      }`}
      </style>
      
      {/* Video Element */}
      {!hasError && (
        <video
          id="bg-video"
          ref={videoRef}
          autoPlay
          muted
          playsInline
          preload="auto"
          onEnded={handleVideoEnd}
          onError={handleVideoError}
          onLoadStart={handleVideoLoadStart}
          onCanPlay={handleVideoCanPlay}
          onCanPlayThrough={handleVideoCanPlayThrough}
          style={{
            ...videoStyles,
            opacity: isLoading ? 0 : 1,
            transition: 'opacity 0.5s ease-in-out'
          }}
          onClick={handleEnableAudio}
        >
          <source
            key={videoSources[currentVideo].src}
            src={videoSources[currentVideo].src}
            type={videoSources[currentVideo].type}
          />
          Your browser does not support the video tag.
        </video>
      )}
      
      {/* Loading Overlay */}
      {isLoading && !hasError && (
        <div style={{
          ...overlayStyles,
          background: 'rgba(0, 0, 0, 0.8)',
          flexDirection: 'column',
          gap: '20px',
          zIndex: 20001
        }}>
          <div className="loading-spinner" style={{
            width: '50px',
            height: '50px',
            border: '5px solid rgba(255, 255, 255, 0.3)',
            borderRadius: '50%',
            borderTopColor: '#fff',
            animation: 'spin 1s ease-in-out infinite'
          }}></div>
          <div>Loading video {currentVideo + 1} of {videoSources.length}...</div>
        </div>
      )}
      
      {/* Error State */}
      {hasError && (
        <div style={{
          ...overlayStyles,
          background: 'rgba(0, 0, 0, 0.9)',
          flexDirection: 'column',
          textAlign: 'center',
          padding: '20px',
          zIndex: 20001
        }}>
          <h2>Unable to load video</h2>
          <p>We're having trouble loading the video content.</p>
          <button 
            onClick={() => window.location.reload()}
            style={{
              marginTop: '20px',
              padding: '10px 20px',
              fontSize: '1rem',
              backgroundColor: '#4CAF50',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Try Again
          </button>
        </div>
      )}
      
      <div
        id="bottom-center-text"
        className="moothedath-text"
        ref={textRef}
        style={{
          ...textStyles,
          display: hasError ? 'block' : 'none'
        }}
        onClick={handleTextClick}
      >
        The Moothedath
      </div>
    </>
  );
}

export default Intro; 