import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, query, where, getDocs, onSnapshot } from 'firebase/firestore';
import PageContainer from './PageContainer';

// No default channel - only active live streams should open

const features = [
  {
    icon: '🔐',
    title: 'Login / Registration',
    desc: 'Family members can securely log in or register to access upload and private features.'
  },
  {
    icon: '🖼️',
    title: 'Photo & Video Upload Portal',
    desc: 'Secure family login to upload images (JPEG, PNG, WebP) and videos (MP4, MOV) with captions, event names, dates, and tags.'
  },
  {
    icon: '🗂️',
    title: 'Photo & Video Gallery',
    desc: 'Filter by year, event, person, or location. Grid/slideshow view, fullscreen lightbox, download/share options.'
  },
  {
    icon: '🧭',
    title: 'Events Section',
    desc: 'Current, upcoming, and past events with photo streams, live updates, RSVP, countdowns, and archives.'
  },
  {
    icon: '💬',
    title: 'Live Chat & Guestbook',
    desc: 'Family/public chat, WhatsApp integration, guestbook for messages, memories, and photo comments.'
  },
  {
    icon: '🧾',
    title: 'About the Ancestral House',
    desc: 'History timeline, interactive family tree, architectural highlights, and renovation stories.'
  },
  {
    icon: '📥',
    title: 'Contribution Section',
    desc: 'Volunteer signup, donation gateway, polls, and feedback forms.'
  },
  {
    icon: '📺',
    title: 'Live Broadcast',
    desc: 'Watch live broadcasts and family content from our official YouTube channel (family.moothedathhouse@gmail.com).'
  }
];

function Home() {
  const [activeLiveStream, setActiveLiveStream] = useState(null);
  const [isLiveStreamEnabled, setIsLiveStreamEnabled] = useState(false);

  // Check for active live streams
  useEffect(() => {
    const liveStreamQuery = query(
      collection(db, 'liveStreams'), 
      where('isActive', '==', true)
    );
    
    const unsubscribe = onSnapshot(liveStreamQuery, (snapshot) => {
      if (!snapshot.empty) {
        const liveStream = snapshot.docs[0].data();
        console.log('Active live stream found:', liveStream);
        setActiveLiveStream(liveStream);
        setIsLiveStreamEnabled(true);
      } else {
        console.log('No active live streams found');
        setActiveLiveStream(null);
        setIsLiveStreamEnabled(false);
      }
    });

    return () => unsubscribe();
  }, []);

  // Developer tag component for middle content
  const developerTag = (
    <div style={{ 
      textAlign: 'center', 
      padding: '0.5rem 0'
    }}>
      <div className="developer-tag" style={{
        display: 'inline-block',
        background: 'rgba(255,255,255,0.3)',
        padding: '0.5rem 1rem',
        borderRadius: '6px',
        boxShadow: '0 1px 5px rgba(0,0,0,0.1)',
        border: '1px solid rgba(255,255,255,0.2)',
        animation: 'pulse 2s ease-in-out infinite'
      }}>
        <p style={{ 
          color: '#ffffff', 
          fontSize: '1rem', 
          margin: 0,
          fontWeight: '500',
          textShadow: '0 1px 2px rgba(255,255,255,0.6), 1px 1px 0px #000, -1px -1px 0px #000, 1px -1px 0px #000, -1px 1px 0px #000',
          animation: 'rainbow 4s linear infinite'
        }}>
          Developed by Rajesh Kumar Menon Moothedath
        </p>
      </div>
    </div>
  );

  return (
    <div style={{ position: 'relative' }}>
      <PageContainer middleContent={developerTag}>
        <h1 style={{ color: '#222', fontSize: '2rem', marginBottom: '1rem', position: 'relative', zIndex: 10, fontWeight: 'bold', textShadow: '0 2px 8px rgba(255,255,255,0.7), 0 1px 2px rgba(0,0,0,0.15)', textAlign: 'center' }}>Welcome to The Moothedath Ancestral House Website</h1>
        <p style={{ color: '#222', fontSize: '1rem', marginBottom: '1.5rem', position: 'relative', zIndex: 10, fontWeight: 'bold', textShadow: '0 2px 8px rgba(255,255,255,0.7), 0 1px 2px rgba(0,0,0,0.15)', textAlign: 'center' }}>
        A digital heritage platform dedicated to preserving and celebrating the charm, legacy, and stories of your ancestral home. This website serves as a virtual showcase and community hub, offering a rich visual and interactive experience for family members, guests, and<br />well-wishers.
      </p>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1rem' }}>
        {features.map((f, i) => {
          const isLiveBroadcast = f.title === 'Live Broadcast';
          const isEnabled = isLiveBroadcast ? isLiveStreamEnabled : true;
          
          return (
            <div key={i} style={{ 
              background: 'transparent', 
              borderRadius: '40px 8px 40px 8px', 
              padding: '1.2rem 1rem', 
              boxShadow: '0 2px 8px rgba(0,0,0,0.04)',
              cursor: isLiveBroadcast && isEnabled ? 'pointer' : 'default',
              transition: isLiveBroadcast ? 'all 0.3s ease' : 'none',
              position: 'relative',
              opacity: isLiveBroadcast && !isEnabled ? 0.6 : 1
            }}
            onClick={isLiveBroadcast && isEnabled && activeLiveStream && activeLiveStream.streamUrl ? () => {
              // Validate URL to prevent opening unwanted URLs
              const url = activeLiveStream.streamUrl;
              if (url && !url.includes('usernamerajesh75') && !url.includes('@usernamerajesh75')) {
                console.log('Opening live stream URL:', url);
                window.open(url, '_blank');
              } else {
                console.log('Blocked unwanted URL:', url);
                alert('Live stream URL is not available or invalid.');
              }
            } : undefined}
            onMouseEnter={isLiveBroadcast && isEnabled ? (e) => {
              e.target.style.transform = 'translateY(-5px)';
              e.target.style.boxShadow = '0 8px 16px rgba(220, 53, 69, 0.2)';
            } : undefined}
            onMouseLeave={isLiveBroadcast && isEnabled ? (e) => {
              e.target.style.transform = 'translateY(0)';
              e.target.style.boxShadow = '0 2px 8px rgba(0,0,0,0.04)';
            } : undefined}
            >
              <div style={{ fontSize: '2.2rem', marginBottom: 8 }}>{f.icon}</div>
              <div style={{ 
                fontWeight: 'bold', 
                fontSize: '1.1rem', 
                marginBottom: 6,
                color: isLiveBroadcast ? '#dc3545' : '#222'
              }}>{f.title}</div>
              <div style={{ 
                color: isLiveBroadcast ? '#dc3545' : '#28a745', 
                fontSize: '0.98rem',
                textShadow: isLiveBroadcast 
                  ? '0.5px 0.5px 1px rgba(0,0,0,0.8), -0.5px -0.5px 1px rgba(0,0,0,0.8), 0.5px -0.5px 1px rgba(0,0,0,0.8), -0.5px 0.5px 1px rgba(0,0,0,0.8)'
                  : '0.5px 0.5px 1px rgba(0,0,0,0.8), -0.5px -0.5px 1px rgba(0,0,0,0.8), 0.5px -0.5px 1px rgba(0,0,0,0.8), -0.5px 0.5px 1px rgba(0,0,0,0.8)'
              }}>
                {isLiveBroadcast && !isEnabled 
                  ? 'Live broadcast is currently offline. Check back later for live events.'
                  : f.desc
                }
              </div>
              {isLiveBroadcast && isEnabled && (
                <div style={{
                  position: 'absolute',
                  top: '0.5rem',
                  right: '0.5rem',
                  background: '#dc3545',
                  color: 'white',
                  padding: '0.2rem 0.5rem',
                  borderRadius: '12px',
                  fontSize: '0.7rem',
                  fontWeight: 'bold',
                  animation: 'pulse 1.5s ease-in-out infinite'
                }}>
                  🔴 LIVE
                </div>
              )}
              {isLiveBroadcast && !isEnabled && (
                <div style={{
                  position: 'absolute',
                  top: '0.5rem',
                  right: '0.5rem',
                  background: '#6c757d',
                  color: 'white',
                  padding: '0.2rem 0.5rem',
                  borderRadius: '12px',
                  fontSize: '0.7rem',
                  fontWeight: 'bold'
                }}>
                  ⚫ OFFLINE
                </div>
              )}
            </div>
          );
        })}
        </div>
      </PageContainer>
      
      <style>
        {`
          @keyframes pulse {
            0% { transform: scale(1); }
            50% { transform: scale(1.05); }
            100% { transform: scale(1); }
          }
          
          @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
          }
          
          @keyframes rainbow {
            0% { color: #ff0000; }
            14% { color: #ff8000; }
            28% { color: #ffff00; }
            42% { color: #00ff00; }
            56% { color: #0080ff; }
            70% { color: #8000ff; }
            84% { color: #ff0080; }
            100% { color: #ff0000; }
          }
        `}
      </style>
    </div>
  );
}

export default Home; 