import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, getDocs, doc, updateDoc, deleteDoc, query, orderBy, where } from 'firebase/firestore';
import PageContainer from './PageContainer';

function AdminDashboard({ currentUser }) {
  const [activeTab, setActiveTab] = useState('approvals');
  const [pendingUploads, setPendingUploads] = useState([]);
  const [approvedUploads, setApprovedUploads] = useState([]);
  const [guestbookEntries, setGuestbookEntries] = useState([]);
  const [chatMessages, setChatMessages] = useState([]);
  const [galleryPhotos, setGalleryPhotos] = useState([]);
  const [events, setEvents] = useState([]);
  const [users, setUsers] = useState([]);
  const [stats, setStats] = useState({
    totalUploads: 0,
    pendingApprovals: 0,
    approvedUploads: 0,
    totalUsers: 0,
    guestbookEntries: 0,
    chatMessages: 0,
    galleryPhotos: 0,
    events: 0,
    recentActivity: []
  });
  const [loading, setLoading] = useState(true);

  // Fetch data on component mount
  useEffect(() => {
    fetchAdminData();
  }, []);

  const fetchAdminData = async () => {
    try {
      setLoading(true);
      
      // Fetch pending uploads
      const pendingQuery = query(collection(db, 'media'), where('approvalStatus', '==', 'pending'));
      const pendingSnapshot = await getDocs(pendingQuery);
      const pendingData = pendingSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setPendingUploads(pendingData);

      // Fetch approved uploads
      const approvedQuery = query(collection(db, 'media'), where('approvalStatus', '==', 'approved'));
      const approvedSnapshot = await getDocs(approvedQuery);
      const approvedData = approvedSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setApprovedUploads(approvedData);

      // Fetch guestbook entries
      const guestbookQuery = query(collection(db, 'guestbook'), orderBy('date', 'desc'));
      const guestbookSnapshot = await getDocs(guestbookQuery);
      const guestbookData = guestbookSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setGuestbookEntries(guestbookData);

      // Fetch chat messages
      const chatQuery = query(collection(db, 'chat'), orderBy('time', 'desc'));
      const chatSnapshot = await getDocs(chatQuery);
      const chatData = chatSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setChatMessages(chatData);

      // Fetch gallery photos (approved media)
      setGalleryPhotos(approvedData);

      // Fetch events
      const eventsQuery = query(collection(db, 'upcomingEvents'), orderBy('date', 'desc'));
      const eventsSnapshot = await getDocs(eventsQuery);
      const eventsData = eventsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setEvents(eventsData);

      // Fetch all uploads for stats
      const allUploadsQuery = query(collection(db, 'media'), orderBy('uploadDate', 'desc'));
      const allUploadsSnapshot = await getDocs(allUploadsQuery);
      const allUploadsData = allUploadsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      // Calculate stats
      setStats({
        totalUploads: allUploadsData.length,
        pendingApprovals: pendingData.length,
        approvedUploads: approvedData.length,
        totalUsers: allUploadsData.reduce((acc, upload) => {
          if (!acc.includes(upload.uploadedBy)) acc.push(upload.uploadedBy);
          return acc;
        }, []).length,
        guestbookEntries: guestbookData.length,
        chatMessages: chatData.length,
        galleryPhotos: approvedData.length,
        events: eventsData.length,
        recentActivity: allUploadsData.slice(0, 10) // Last 10 uploads
      });

    } catch (error) {
      console.error('Error fetching admin data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleApproval = async (uploadId, status) => {
    try {
      const uploadRef = doc(db, 'media', uploadId);
      await updateDoc(uploadRef, {
        approvalStatus: status,
        approvedBy: currentUser.email,
        approvedAt: new Date().toISOString()
      });

      // Refresh data
      await fetchAdminData();
      alert(`Upload ${status === 'approved' ? 'approved' : 'rejected'} successfully!`);
    } catch (error) {
      console.error('Error updating approval status:', error);
      alert('Error updating approval status');
    }
  };

  const handleDeleteUpload = async (uploadId) => {
    if (window.confirm('Are you sure you want to delete this upload? This action cannot be undone.')) {
      try {
        await deleteDoc(doc(db, 'media', uploadId));
        await fetchAdminData();
        alert('Upload deleted successfully!');
      } catch (error) {
        console.error('Error deleting upload:', error);
        alert('Error deleting upload');
      }
    }
  };

  const handleDeleteGuestbookEntry = async (entryId) => {
    if (window.confirm('Are you sure you want to delete this guestbook entry? This action cannot be undone.')) {
      try {
        await deleteDoc(doc(db, 'guestbook', entryId));
        await fetchAdminData();
        alert('Guestbook entry deleted successfully!');
      } catch (error) {
        console.error('Error deleting guestbook entry:', error);
        alert('Error deleting guestbook entry');
      }
    }
  };

  const handleDeleteChatMessage = async (messageId) => {
    if (window.confirm('Are you sure you want to delete this chat message? This action cannot be undone.')) {
      try {
        await deleteDoc(doc(db, 'chat', messageId));
        await fetchAdminData();
        alert('Chat message deleted successfully!');
      } catch (error) {
        console.error('Error deleting chat message:', error);
        alert('Error deleting chat message');
      }
    }
  };

  const handleDeleteEvent = async (eventId) => {
    if (window.confirm('Are you sure you want to delete this event? This action cannot be undone.')) {
      try {
        await deleteDoc(doc(db, 'upcomingEvents', eventId));
        await fetchAdminData();
        alert('Event deleted successfully!');
      } catch (error) {
        console.error('Error deleting event:', error);
        alert('Error deleting event');
      }
    }
  };

  const formatDate = (timestamp) => {
    if (!timestamp) return 'N/A';
    const date = timestamp.toDate ? timestamp.toDate() : new Date(timestamp);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <PageContainer>
        <div style={{ textAlign: 'center', padding: '2rem' }}>
          <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>⏳</div>
          <p>Loading admin dashboard...</p>
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer>
      <div style={{ background: 'transparent', padding: '2rem', borderRadius: 12, boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}>
        <h1 style={{ color: '#dc3545', fontSize: '2rem', marginBottom: '1rem', textAlign: 'center' }}>
          👑 Administrator Dashboard
        </h1>
        <p style={{ color: '#666', textAlign: 'center', marginBottom: '2rem' }}>
          Welcome, {currentUser?.displayName || currentUser?.email}. Manage website content and user uploads.
        </p>

        {/* Admin Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem', marginBottom: '2rem' }}>
          <div style={{ background: 'rgba(220, 53, 69, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #dc3545' }}>
            <h3 style={{ color: '#dc3545', margin: '0 0 0.5rem 0' }}>📊 Total Uploads</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.totalUploads}</p>
          </div>
          <div style={{ background: 'rgba(255, 193, 7, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #ffc107' }}>
            <h3 style={{ color: '#856404', margin: '0 0 0.5rem 0' }}>⏳ Pending Approvals</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.pendingApprovals}</p>
          </div>
          <div style={{ background: 'rgba(40, 167, 69, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #28a745' }}>
            <h3 style={{ color: '#155724', margin: '0 0 0.5rem 0' }}>✅ Approved</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.approvedUploads}</p>
          </div>
          <div style={{ background: 'rgba(0, 123, 255, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #007bff' }}>
            <h3 style={{ color: '#004085', margin: '0 0 0.5rem 0' }}>👥 Total Users</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.totalUsers}</p>
          </div>
          <div style={{ background: 'rgba(111, 66, 193, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #6f42c1' }}>
            <h3 style={{ color: '#6f42c1', margin: '0 0 0.5rem 0' }}>📖 Guestbook</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.guestbookEntries}</p>
          </div>
          <div style={{ background: 'rgba(23, 162, 184, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #17a2b8' }}>
            <h3 style={{ color: '#17a2b8', margin: '0 0 0.5rem 0' }}>💬 Chat Messages</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.chatMessages}</p>
          </div>
          <div style={{ background: 'rgba(253, 126, 20, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #fd7e14' }}>
            <h3 style={{ color: '#fd7e14', margin: '0 0 0.5rem 0' }}>📷 Gallery Photos</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.galleryPhotos}</p>
          </div>
          <div style={{ background: 'rgba(108, 117, 125, 0.1)', padding: '1rem', borderRadius: 8, textAlign: 'center', border: '1px solid #6c757d' }}>
            <h3 style={{ color: '#6c757d', margin: '0 0 0.5rem 0' }}>📅 Events</h3>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', margin: 0 }}>{stats.events}</p>
          </div>
        </div>

        {/* Tab Navigation */}
        <div style={{ display: 'flex', gap: '1rem', marginBottom: '2rem', flexWrap: 'wrap' }}>
          <button
            onClick={() => setActiveTab('approvals')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'approvals' ? '#dc3545' : 'transparent',
              color: activeTab === 'approvals' ? 'white' : '#dc3545',
              cursor: 'pointer',
              fontWeight: activeTab === 'approvals' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            ⏳ Pending Approvals ({stats.pendingApprovals})
          </button>
          <button
            onClick={() => setActiveTab('approved')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'approved' ? '#28a745' : 'transparent',
              color: activeTab === 'approved' ? 'white' : '#28a745',
              cursor: 'pointer',
              fontWeight: activeTab === 'approved' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            ✅ Approved Content ({stats.approvedUploads})
          </button>
          <button
            onClick={() => setActiveTab('guestbook')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'guestbook' ? '#6f42c1' : 'transparent',
              color: activeTab === 'guestbook' ? 'white' : '#6f42c1',
              cursor: 'pointer',
              fontWeight: activeTab === 'guestbook' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            📖 Guestbook ({stats.guestbookEntries})
          </button>
          <button
            onClick={() => setActiveTab('chat')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'chat' ? '#17a2b8' : 'transparent',
              color: activeTab === 'chat' ? 'white' : '#17a2b8',
              cursor: 'pointer',
              fontWeight: activeTab === 'chat' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            💬 Chat Messages ({stats.chatMessages})
          </button>
          <button
            onClick={() => setActiveTab('gallery')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'gallery' ? '#fd7e14' : 'transparent',
              color: activeTab === 'gallery' ? 'white' : '#fd7e14',
              cursor: 'pointer',
              fontWeight: activeTab === 'gallery' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            📷 Gallery Photos ({stats.galleryPhotos})
          </button>
          <button
            onClick={() => setActiveTab('events')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'events' ? '#6c757d' : 'transparent',
              color: activeTab === 'events' ? 'white' : '#6c757d',
              cursor: 'pointer',
              fontWeight: activeTab === 'events' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            📅 Events ({stats.events})
          </button>
          <button
            onClick={() => setActiveTab('stats')}
            style={{
              padding: '0.75rem 1.5rem',
              border: 'none',
              borderRadius: 8,
              background: activeTab === 'stats' ? '#007bff' : 'transparent',
              color: activeTab === 'stats' ? 'white' : '#007bff',
              cursor: 'pointer',
              fontWeight: activeTab === 'stats' ? 'bold' : 'normal',
              fontSize: '1.1rem',
              transition: 'all 0.3s ease'
            }}
          >
            📊 Statistics
          </button>
        </div>

        {/* Pending Approvals Tab */}
        {activeTab === 'approvals' && (
          <div>
            <h2 style={{ color: '#dc3545', fontSize: '1.5rem', marginBottom: '1rem' }}>
              ⏳ Pending Approvals ({pendingUploads.length})
            </h2>
            {pendingUploads.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#666' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>✅</div>
                <p>No pending approvals! All uploads have been reviewed.</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '1rem' }}>
                {pendingUploads.map((upload) => (
                  <div key={upload.id} style={{ 
                    background: 'white', 
                    padding: '1rem', 
                    borderRadius: 8, 
                    border: '1px solid #ddd',
                    display: 'grid',
                    gridTemplateColumns: '1fr 2fr 1fr',
                    gap: '1rem',
                    alignItems: 'center'
                  }}>
                    <div>
                      {upload.type === 'image' ? (
                        <img 
                          src={upload.url} 
                          alt={upload.title}
                          style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: 8 }}
                        />
                      ) : (
                        <video 
                          src={upload.url} 
                          style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: 8 }}
                          controls
                        />
                      )}
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 0.5rem 0', color: '#333' }}>{upload.title}</h4>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Uploaded by:</strong> {upload.uploadedBy}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Date:</strong> {formatDate(upload.uploadDate)}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Event:</strong> {upload.event}
                      </p>
                      {upload.caption && (
                        <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>
                          <strong>Caption:</strong> {upload.caption}
                        </p>
                      )}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <button
                        onClick={() => handleApproval(upload.id, 'approved')}
                        style={{
                          background: '#28a745',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        ✅ Approve
                      </button>
                      <button
                        onClick={() => handleApproval(upload.id, 'rejected')}
                        style={{
                          background: '#dc3545',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        ❌ Reject
                      </button>
                      <button
                        onClick={() => handleDeleteUpload(upload.id)}
                        style={{
                          background: '#6c757d',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        🗑️ Delete
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Approved Content Tab */}
        {activeTab === 'approved' && (
          <div>
            <h2 style={{ color: '#28a745', fontSize: '1.5rem', marginBottom: '1rem' }}>
              ✅ Approved Content ({approvedUploads.length})
            </h2>
            {approvedUploads.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#666' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📷</div>
                <p>No approved content yet. Approve some uploads to see them here.</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '1rem' }}>
                {approvedUploads.map((upload) => (
                  <div key={upload.id} style={{ 
                    background: 'white', 
                    padding: '1rem', 
                    borderRadius: 8, 
                    border: '1px solid #ddd',
                    display: 'grid',
                    gridTemplateColumns: '1fr 2fr 1fr',
                    gap: '1rem',
                    alignItems: 'center'
                  }}>
                    <div>
                      {upload.type === 'image' ? (
                        <img 
                          src={upload.url} 
                          alt={upload.title}
                          style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: 8 }}
                        />
                      ) : (
                        <video 
                          src={upload.url} 
                          style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: 8 }}
                          controls
                        />
                      )}
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 0.5rem 0', color: '#333' }}>{upload.title}</h4>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Uploaded by:</strong> {upload.uploadedBy}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Approved by:</strong> {upload.approvedBy}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Approved on:</strong> {formatDate(upload.approvedAt)}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Event:</strong> {upload.event}
                      </p>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <button
                        onClick={() => handleApproval(upload.id, 'pending')}
                        style={{
                          background: '#ffc107',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        ⏳ Unapprove
                      </button>
                      <button
                        onClick={() => handleDeleteUpload(upload.id)}
                        style={{
                          background: '#6c757d',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        🗑️ Delete
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Statistics Tab */}
        {activeTab === 'stats' && (
          <div>
            <h2 style={{ color: '#007bff', fontSize: '1.5rem', marginBottom: '1rem' }}>
              📊 Website Statistics
            </h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem' }}>
              <div style={{ background: 'white', padding: '1.5rem', borderRadius: 8, border: '1px solid #ddd' }}>
                <h3 style={{ color: '#333', marginBottom: '1rem' }}>📈 Upload Statistics</h3>
                <div style={{ display: 'grid', gap: '0.5rem' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Total Uploads:</span>
                    <strong>{stats.totalUploads}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Pending Approvals:</span>
                    <strong style={{ color: '#ffc107' }}>{stats.pendingApprovals}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Approved Uploads:</span>
                    <strong style={{ color: '#28a745' }}>{stats.approvedUploads}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Approval Rate:</span>
                    <strong>
                      {stats.totalUploads > 0 
                        ? Math.round((stats.approvedUploads / stats.totalUploads) * 100) 
                        : 0}%
                    </strong>
                  </div>
                </div>
              </div>

              <div style={{ background: 'white', padding: '1.5rem', borderRadius: 8, border: '1px solid #ddd' }}>
                <h3 style={{ color: '#333', marginBottom: '1rem' }}>👥 User Statistics</h3>
                <div style={{ display: 'grid', gap: '0.5rem' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Total Users:</span>
                    <strong>{stats.totalUsers}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Active Contributors:</span>
                    <strong>{stats.approvedUploads > 0 ? 'Yes' : 'No'}</strong>
                  </div>
                </div>
              </div>

              <div style={{ background: 'white', padding: '1.5rem', borderRadius: 8, border: '1px solid #ddd' }}>
                <h3 style={{ color: '#333', marginBottom: '1rem' }}>📊 Content Statistics</h3>
                <div style={{ display: 'grid', gap: '0.5rem' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Guestbook Entries:</span>
                    <strong style={{ color: '#6f42c1' }}>{stats.guestbookEntries}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Chat Messages:</span>
                    <strong style={{ color: '#17a2b8' }}>{stats.chatMessages}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Gallery Photos:</span>
                    <strong style={{ color: '#fd7e14' }}>{stats.galleryPhotos}</strong>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                    <span>Events:</span>
                    <strong style={{ color: '#6c757d' }}>{stats.events}</strong>
                  </div>
                </div>
              </div>

              <div style={{ background: 'white', padding: '1.5rem', borderRadius: 8, border: '1px solid #ddd' }}>
                <h3 style={{ color: '#333', marginBottom: '1rem' }}>🕒 Recent Activity</h3>
                <div style={{ maxHeight: '200px', overflowY: 'auto' }}>
                  {stats.recentActivity.length === 0 ? (
                    <p style={{ color: '#666', textAlign: 'center' }}>No recent activity</p>
                  ) : (
                    <div style={{ display: 'grid', gap: '0.5rem' }}>
                      {stats.recentActivity.map((activity, index) => (
                        <div key={index} style={{ 
                          padding: '0.5rem', 
                          background: '#f8f9fa', 
                          borderRadius: 4,
                          fontSize: '0.9rem'
                        }}>
                          <div style={{ fontWeight: 'bold' }}>{activity.title}</div>
                          <div style={{ color: '#666' }}>
                            {activity.uploadedBy} • {formatDate(activity.uploadDate)}
                          </div>
                          <div style={{ 
                            color: activity.approvalStatus === 'approved' ? '#28a745' : 
                                   activity.approvalStatus === 'pending' ? '#ffc107' : '#dc3545'
                          }}>
                            {activity.approvalStatus?.toUpperCase() || 'PENDING'}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Guestbook Management Tab */}
        {activeTab === 'guestbook' && (
          <div>
            <h2 style={{ color: '#6f42c1', fontSize: '1.5rem', marginBottom: '1rem' }}>
              📖 Guestbook Management ({guestbookEntries.length})
            </h2>
            {guestbookEntries.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#666' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📖</div>
                <p>No guestbook entries found.</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '1rem' }}>
                {guestbookEntries.map((entry) => (
                  <div key={entry.id} style={{ 
                    background: 'white', 
                    padding: '1rem', 
                    borderRadius: 8, 
                    border: '1px solid #ddd',
                    display: 'grid',
                    gridTemplateColumns: '1fr 2fr 1fr',
                    gap: '1rem',
                    alignItems: 'center'
                  }}>
                    <div>
                      {entry.photo && (
                        <img 
                          src={entry.photo} 
                          alt={entry.name}
                          style={{ width: '80px', height: '80px', objectFit: 'cover', borderRadius: '50%' }}
                        />
                      )}
                      {!entry.photo && (
                        <div style={{ 
                          width: '80px', 
                          height: '80px', 
                          background: '#6f42c1', 
                          borderRadius: '50%',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: 'white',
                          fontSize: '2rem'
                        }}>
                          👤
                        </div>
                      )}
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 0.5rem 0', color: '#333' }}>{entry.name}</h4>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Date:</strong> {formatDate(entry.date)}
                      </p>
                      <p style={{ margin: '0', color: '#333', fontSize: '0.9rem' }}>
                        {entry.message}
                      </p>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <button
                        onClick={() => handleDeleteGuestbookEntry(entry.id)}
                        style={{
                          background: '#dc3545',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        🗑️ Delete Entry
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Chat Messages Management Tab */}
        {activeTab === 'chat' && (
          <div>
            <h2 style={{ color: '#17a2b8', fontSize: '1.5rem', marginBottom: '1rem' }}>
              💬 Chat Messages Management ({chatMessages.length})
            </h2>
            {chatMessages.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#666' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>💬</div>
                <p>No chat messages found.</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '1rem' }}>
                {chatMessages.map((message) => (
                  <div key={message.id} style={{ 
                    background: 'white', 
                    padding: '1rem', 
                    borderRadius: 8, 
                    border: '1px solid #ddd',
                    display: 'grid',
                    gridTemplateColumns: '2fr 1fr',
                    gap: '1rem',
                    alignItems: 'center'
                  }}>
                    <div>
                      <h4 style={{ margin: '0 0 0.5rem 0', color: '#333' }}>{message.name}</h4>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Time:</strong> {message.time}
                      </p>
                      <p style={{ margin: '0', color: '#333', fontSize: '0.9rem' }}>
                        {message.message}
                      </p>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <button
                        onClick={() => handleDeleteChatMessage(message.id)}
                        style={{
                          background: '#dc3545',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        🗑️ Delete Message
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Gallery Photos Management Tab */}
        {activeTab === 'gallery' && (
          <div>
            <h2 style={{ color: '#fd7e14', fontSize: '1.5rem', marginBottom: '1rem' }}>
              📷 Gallery Photos Management ({galleryPhotos.length})
            </h2>
            {galleryPhotos.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#666' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📷</div>
                <p>No gallery photos found.</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '1rem' }}>
                {galleryPhotos.map((photo) => (
                  <div key={photo.id} style={{ 
                    background: 'white', 
                    padding: '1rem', 
                    borderRadius: 8, 
                    border: '1px solid #ddd',
                    display: 'grid',
                    gridTemplateColumns: '1fr 2fr 1fr',
                    gap: '1rem',
                    alignItems: 'center'
                  }}>
                    <div>
                      {photo.type === 'image' ? (
                        <img 
                          src={photo.url} 
                          alt={photo.title}
                          style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: 8 }}
                        />
                      ) : (
                        <video 
                          src={photo.url} 
                          style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: 8 }}
                          controls
                        />
                      )}
                    </div>
                    <div>
                      <h4 style={{ margin: '0 0 0.5rem 0', color: '#333' }}>{photo.title}</h4>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Uploaded by:</strong> {photo.uploadedBy}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Event:</strong> {photo.event}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Location:</strong> {photo.location}
                      </p>
                      {photo.caption && (
                        <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>
                          <strong>Caption:</strong> {photo.caption}
                        </p>
                      )}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <button
                        onClick={() => handleApproval(photo.id, 'pending')}
                        style={{
                          background: '#ffc107',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        ⏳ Unapprove
                      </button>
                      <button
                        onClick={() => handleDeleteUpload(photo.id)}
                        style={{
                          background: '#dc3545',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        🗑️ Delete
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Events Management Tab */}
        {activeTab === 'events' && (
          <div>
            <h2 style={{ color: '#6c757d', fontSize: '1.5rem', marginBottom: '1rem' }}>
              📅 Events Management ({events.length})
            </h2>
            {events.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '2rem', color: '#666' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📅</div>
                <p>No events found.</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '1rem' }}>
                {events.map((event) => (
                  <div key={event.id} style={{ 
                    background: 'white', 
                    padding: '1rem', 
                    borderRadius: 8, 
                    border: '1px solid #ddd',
                    display: 'grid',
                    gridTemplateColumns: '2fr 1fr',
                    gap: '1rem',
                    alignItems: 'center'
                  }}>
                    <div>
                      <h4 style={{ margin: '0 0 0.5rem 0', color: '#333' }}>{event.title}</h4>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Date:</strong> {formatDate(event.date)}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Location:</strong> {event.location}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Description:</strong> {event.description}
                      </p>
                      <p style={{ margin: '0 0 0.5rem 0', color: '#666', fontSize: '0.9rem' }}>
                        <strong>Attendees:</strong> {event.attendees || 0}
                      </p>
                      {event.contributor && (
                        <p style={{ margin: '0', color: '#666', fontSize: '0.9rem' }}>
                          <strong>Contributed by:</strong> {event.contributor}
                        </p>
                      )}
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                      <button
                        onClick={() => handleDeleteEvent(event.id)}
                        style={{
                          background: '#dc3545',
                          color: 'white',
                          border: 'none',
                          padding: '0.5rem 1rem',
                          borderRadius: 6,
                          cursor: 'pointer',
                          fontSize: '0.9rem'
                        }}
                      >
                        🗑️ Delete Event
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </PageContainer>
  );
}

export default AdminDashboard; 